import{_ as r,C as n,o as t,c as s,a2 as a,b as i,w as o,a as c,E as l,a3 as h}from"./chunks/framework.C_fNVUec.js";const p="/orc/screens/orc-tour.gif",C=JSON.parse('{"title":"What is ORC","description":"","frontmatter":{},"headers":[],"relativePath":"docs/what-is-orc.md","filePath":"docs/what-is-orc.md","lastUpdated":1793898059000}'),u={name:"docs/what-is-orc.md"};function g(m,e,b,w,A,f){const d=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="what-is-orc" tabindex="-1">What is ORC <a class="header-anchor" href="#what-is-orc" aria-label="Permalink to &quot;What is ORC&quot;">​</a></h1><p>This page explains the problem ORC solves, what it gives you, who it is for, and how its parts fit together.</p><p><img src="'+p+'" alt="A tour of the ORC dashboard: activity, task board, task flow, agent sessions and the terminal"></p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Every coding-agent session is an island.</p><ul><li>A new Claude Code, Codex or Cursor session knows nothing about the last one.</li><li>Two sessions running in parallel cannot coordinate.</li><li>Switching agents means starting from zero.</li><li>There is no shared board: work in flight lives in terminal tabs and your head.</li><li>There is no middle ground between full autonomy and watching every step. You cannot say &quot;do the work, but check with me before it lands.&quot;</li></ul><p>You end up as the integration layer, copying context between sessions by hand.</p><h2 id="what-orc-gives-you" tabindex="-1">What ORC gives you <a class="header-anchor" href="#what-orc-gives-you" aria-label="Permalink to &quot;What ORC gives you&quot;">​</a></h2><p>ORC is a self-hosted hub that every agent session connects to. It holds shared state, routes work, and puts your approval between &quot;the agent thinks it is done&quot; and &quot;done&quot;.</p><table tabindex="0"><thead><tr><th>Capability</th><th>What you get</th></tr></thead><tbody><tr><td>Task board</td><td><code>todo → queued → doing → review → done</code>, with dependencies, priority and a <code>review</code> gate you approve</td></tr><tr><td>Agent orchestration</td><td>A task loop that claims queued tasks and runs workers on Claude, Codex, ACPX agents, agentapi or A2A endpoints</td></tr><tr><td>Task flows</td><td>Per-task graphs: build, verify, review loops, parallel fan-out, human gates, hard termination limits</td></tr><tr><td>Shared memory</td><td>Short project facts loaded into every session&#39;s context</td></tr><tr><td>Knowledge bases</td><td>Uploaded documents and folders with full-text and vector search, cited passages</td></tr><tr><td>Sessions</td><td>One view of live and ended Claude Code, Codex, Cursor and Gemini sessions, with transcripts, resume and handoff</td></tr><tr><td>Scratchpads</td><td>Plans, diagrams and HTML pages that you and agents edit together, with revisions</td></tr><tr><td>Jobs and webhooks</td><td>Commands, agent runs or task creation on cron, file-watch, webhook or manual triggers</td></tr><tr><td>Channels</td><td>Telegram and Slack: get notified, approve, chat with agents from your phone</td></tr><tr><td>Attention</td><td>Agent questions, approvals and command requests in one inbox</td></tr><tr><td>Rules</td><td>Deterministic allow/deny/ask decisions on agent tool calls</td></tr><tr><td>Skills and packages</td><td>A shared library of skills and agent profiles every backend can use</td></tr></tbody></table><p>Everything is stored in one SQLite file plus a folder of files under <code>~/.orc</code>. There is no account and no hosted service.</p><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><p>Developers who:</p><ul><li>run several agent sessions, serial or parallel, that need shared context</li><li>use more than one coding agent and want one board across them</li><li>want agents to work unattended and submit results for review</li><li>want scheduled agent work they review when convenient</li><li>need a record of what was done, decided and why</li></ul><p>ORC does not write code or replace your agents. It coordinates them.</p><h2 id="how-the-pieces-fit" tabindex="-1">How the pieces fit <a class="header-anchor" href="#how-the-pieces-fit" aria-label="Permalink to &quot;How the pieces fit&quot;">​</a></h2>',16)),(t(),i(h,null,{default:o(()=>[l(d,{id:"mermaid-203",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20Clients%0A%20%20%20%20Web%5BWeb%20dashboard%5D%0A%20%20%20%20Desk%5BDesktop%20app%5D%0A%20%20%20%20CLI%5Borc%20CLI%5D%0A%20%20%20%20Agent%5BClaude%20Code%20%2F%20Codex%20%2F%20Cursor%5D%0A%20%20%20%20Phone%5BTelegram%20%2F%20Slack%5D%0A%20%20end%0A%0A%20%20subgraph%20Daemon%5B%22orc%20daemon%20(%3A7700)%22%5D%0A%20%20%20%20API%5BREST%20API%20%2Fapi%5D%0A%20%20%20%20MCP%5BMCP%20%2Fmcp%5D%0A%20%20%20%20Runner%5BRunner%3A%20task%20loop%2C%20flows%2C%20jobs%5D%0A%20%20%20%20GW%5BChannels%20%2F%20gateway%5D%0A%20%20%20%20Term%5BTerminals%5D%0A%20%20end%0A%0A%20%20DB%5B(orc.db%20%2B%20~%2F.orc%20files)%5D%0A%20%20Backends%5BAgent%20backends%3A%20claude%2C%20codex-cli%2C%20acpx%2C%20agentapi%2C%20a2a%5D%0A%0A%20%20Web%20--%3E%20API%0A%20%20Desk%20--%3E%20API%0A%20%20CLI%20--%3E%20API%0A%20%20Agent%20--%3E%20MCP%0A%20%20Phone%20%3C--%3E%20GW%0A%20%20API%20--%3E%20DB%0A%20%20MCP%20--%3E%20DB%0A%20%20Runner%20--%3E%20DB%0A%20%20Runner%20--%3E%20Backends%0A%20%20GW%20--%3E%20API%0A%20%20Term%20--%3E%20Backends%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<table tabindex="0"><thead><tr><th>Component</th><th>Package</th><th>Role</th></tr></thead><tbody><tr><td>Daemon</td><td><code>packages/cli</code> (<code>orc daemon start</code>)</td><td>One process that runs the API, runner, channels and terminals</td></tr><tr><td>REST API</td><td><code>packages/api</code></td><td>Hono server on port 7700; OpenAPI at <code>/openapi.json</code>, Swagger at <code>/docs</code></td></tr><tr><td>MCP server</td><td><code>packages/mcp</code></td><td>Agent tools over Streamable HTTP at <code>/mcp</code> or stdio via <code>orc mcp</code></td></tr><tr><td>CLI</td><td><code>packages/cli</code></td><td>The <code>orc</code> binary; talks to the API</td></tr><tr><td>Web dashboard</td><td><code>packages/web</code></td><td>React UI served by the daemon at its root URL</td></tr><tr><td>Desktop app</td><td><code>packages/desktop</code></td><td>Bundles the daemon, dashboard and CLI; attaches to a running daemon or starts one</td></tr><tr><td>Runner</td><td><code>packages/runner</code></td><td>Task loop, flow engine, job executor and scheduler</td></tr><tr><td>Agent runtime</td><td><code>packages/agent-runtime</code></td><td>Backend adapters that launch and drive coding agents</td></tr><tr><td>Channels / gateway</td><td><code>packages/channels</code>, <code>packages/gateway</code></td><td>Telegram and Slack transport, routing and agent chat</td></tr><tr><td>Database</td><td><code>packages/db</code></td><td>SQLite via Drizzle, at <code>~/.orc/orc.db</code></td></tr></tbody></table><p>Data flows <code>Agent → MCP → API/DB</code> and <code>CLI → SDK → API → DB</code>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./install">Install</a> and <a href="./quick-start">Quick start</a></li><li><a href="./concepts">Concepts</a> for the core model</li><li><a href="./connect-agents">Connect agents</a></li><li><a href="./self-hosted">Self-hosted ORC</a> to run a remote instance next to your local one</li></ul>',4))])}const v=r(u,[["render",g]]);export{C as __pageData,v as default};
